55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    private final OwnerFieldsValidator ownerFieldsValidator;
71	
72	    private final TelephoneNormalizer telephoneNormalizer;
73	
74	    private final EmailNormalizer emailNormalizer;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 OwnerFieldsValidator ownerFieldsValidator,
81	                                 TelephoneNormalizer telephoneNormalizer,
82	                                 EmailNormalizer emailNormalizer) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.ownerFieldsValidator = ownerFieldsValidator;
88	        this.telephoneNormalizer = telephoneNormalizer;
89	        this.emailNormalizer = emailNormalizer;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        this.ownerFieldsValidator.validate(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
124	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
125	        if (owner.getRegistrationDate() == null) {
126	            owner.setRegistrationDate(LocalDate.now());
127	        }
128	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
129	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
130	        }
131	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
132	            && !this.clinicService.findOwnersInSameHousehold(owner.getLastName(), owner.getAddress()).isEmpty()) {
133	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
134	        }
135	        this.clinicService.saveOwner(owner);
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
145	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
146	        if (currentOwner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        currentOwner.setAddress(ownerFieldsDto.getAddress());
150	        currentOwner.setCity(ownerFieldsDto.getCity());
151	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
152	        currentOwner.setLastName(ownerFieldsDto.getLastName());
153	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
154	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Transactional
161	    @Override
162	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        this.clinicService.deleteOwner(owner);
168	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Pet pet = petMapper.toPet(petFieldsDto);
180	        owner.setId(ownerId);
181	        pet.setOwner(owner);
182	        pet.getType().setName(null);
183	        this.clinicService.savePet(pet);
184	        PetDto petDto = petMapper.toPetDto(pet);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
186	            .buildAndExpand(pet.getId()).toUri());
187	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner != null) {
195	            Pet currentPet = this.clinicService.findPetById(petId);
196	            if (currentPet != null) {
197	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
198	                currentPet.setName(petFieldsDto.getName());
199	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
200	                this.clinicService.savePet(currentPet);
201	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
210	        HttpHeaders headers = new HttpHeaders();
211	        Visit visit = visitMapper.toVisit(visitFieldsDto);
212	        Pet pet = new Pet();
213	        pet.setId(petId);
214	        visit.setPet(pet);
215	        this.clinicService.saveVisit(visit);
216	        VisitDto visitDto = visitMapper.toVisitDto(visit);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
218	            .buildAndExpand(visit.getId()).toUri());
219	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
220	    }
